'use strict';

// The playlist and the small calculations of the player.
// The browser loads this file as a classic script, so the names below are
// globals that index.js can use. Node loads it as a CommonJS module for the
// tests (see the export at the end).

// The audio files are generated by tools/make-loops.mjs.
const tracks = [
    {
        title: 'Paper Lanterns',
        detail: 'Generated loop · C major · 80 BPM',
        src: 'assets/audio/paper-lanterns.m4a',
        cover: 'assets/covers/paper-lanterns.svg',
    },
    {
        title: 'Night Tram',
        detail: 'Generated loop · C major · 86 BPM',
        src: 'assets/audio/night-tram.m4a',
        cover: 'assets/covers/night-tram.svg',
    },
    {
        title: 'Low Tide',
        detail: 'Generated loop · D major · no beat',
        src: 'assets/audio/low-tide.m4a',
        cover: 'assets/covers/low-tide.svg',
    },
];

// After this many seconds "previous" restarts the track instead of leaving it.
const RESTART_AFTER_SECONDS = 3;

// Keeps an index inside 0..length-1; -1 becomes the last index.
// The extra "+ length" is needed because -1 % 3 is -1 in JavaScript.
function wrapIndex(index, length) {
    return ((index % length) + length) % length;
}

// 75.4 -> "1:15". Before the metadata has loaded the duration is NaN.
function formatTime(seconds) {
    if (!Number.isFinite(seconds) || seconds < 0) return '0:00';
    const whole = Math.floor(seconds);
    return `${Math.floor(whole / 60)}:${String(whole % 60).padStart(2, '0')}`;
}

// Where "previous" goes: back to the start of the current track once it has
// played for a moment, otherwise to the track before it.
function previousTarget(index, currentTime, length) {
    if (currentTime > RESTART_AFTER_SECONDS) return { index, restart: true };
    return { index: wrapIndex(index - 1, length), restart: false };
}

// Position after seeking by a number of seconds, kept inside the track.
function seekTarget(currentTime, delta, duration) {
    if (!Number.isFinite(duration)) return currentTime;
    return Math.min(Math.max(currentTime + delta, 0), duration);
}

if (typeof module !== 'undefined') {
    module.exports = { tracks, wrapIndex, formatTime, previousTarget, seekTarget };
}
